use crate::{Action, Actor, Book, Focus, Genre, Register, RustForm, Signal, Story, StoryError};

pub fn apply(story: &mut Story) -> Result<(), StoryError> {
    romans(story)?;
    _1_corinthians(story)?;
    _2_corinthians(story)?;
    galatians(story)?;
    ephesians(story)?;
    philippians(story)?;
    colossians(story)?;
    _1_thessalonians(story)?;
    _2_thessalonians(story)?;
    _1_timothy(story)?;
    _2_timothy(story)?;
    titus(story)?;
    philemon(story)?;
    Ok(())
}

